-- V52: Configure Semester, Duration Weeks and Teaching Courses breakdown for Inxhinieri Informatike Master - Year 2
-- Program: Inxhinieri Informatike (Master Shkencor), Study Year: 2, Duration: 12 weeks

-- Step 1: Update SEMESTER and DURATION_WEEKS on COURSES table
UPDATE FTIAPP.COURSES SET SEMESTER = '1', DURATION_WEEKS = 12 WHERE COURSE_ID = 147; -- Big Data: Arkitektura edhe Analiza e të Dhënave
UPDATE FTIAPP.COURSES SET SEMESTER = '1', DURATION_WEEKS = 12 WHERE COURSE_ID = 148; -- Teknologjitë e bazave të të dhënave
